prompt_excerpts.task_prompt_function:
def task_prompt(task: dict, alternate: bool = False, previous: str = "") -> str:
    data = public_task(task)
    if alternate:
        data["train"] = list(reversed(data["train"]))
    text = "Infer transform(grid) for these demonstrations and test inputs:\n" + json.dumps(data, separators=(",", ":"))
    if alternate:
        text += "\nFind an independently justified rule. Examine ambiguities, background choice, object decomposition and invariances."
        if previous:
            text += "\nAn earlier hypothesis was:\n```python\n" + previous[:12000] + "\n```\nOnly propose a different rule if the demonstrations support it."
    return text

