def repair_feedback(result: dict, task: dict) -> str:
    if "error" in result:
        return "Execution failed: " + result["error"] + "\nReturn the complete corrected transform program."
    failures = []
    for row in result.get("train", []):
        if not row["correct"]:
            failures.append({**row, "expected": task["train"][row["index"]]["output"]})
    if not failures:
        failures.append({"error": "Some test outputs are invalid", "predictions": result.get("predictions")})
    return "The program failed these checks:\n" + json.dumps(failures, separators=(",", ":")) + "\nReconsider the rule using all demonstrations. Return a complete corrected program."
